tool_input.command:
$p="C:\Users\Administrator\.dsh\profiles\web\cordis.patch.yml"
# What preset blocks own lines 369-370 and 716-717? Find nearest preceding "- id: preset-"
$lines = Get-Content $p
$targets = 369,716
foreach($t in $targets){
  for($i=$t-1;$i -ge 0;$i--){
    if($lines[$i] -match '^- id: (preset-\S+)'){ Write-Host "line $t belongs to preset block: $($Matches[1]) (at L$($i+1))"; break }
  }
}
Write-Host "=== all preset block starts ==="
for($i=0;$i -lt $lines.Count;$i++){ if($lines[$i] -match '^- id: (preset-\S+)'){ Write-Host "L$($i+1): $($Matches[1])" } }

$p="C:\Users\Administrator\.dsh\profiles\web\cordis.patch.yml"
$lines = Get-Content $p
Write-Host "=== registry block L311-316 ==="
$lines[310..315] | ForEach-Object {$_}
Write-Host "`n=== does any 'order: 5' already exist? ==="
Select-String -Path $p -Pattern 'order:\s*5' | ForEach-Object {"L$($_.LineNumber): $($_.Line.Trim())"}
Write-Host "=== any 'full-tools' / preset-full-tools / id: full already? ==="
Select-String -Path $p -Pattern 'full-tools|preset-full' | ForEach-Object {"L$($_.LineNumber): $($_.Line.Trim())"}
Write-Host "=== search for a registry 'presets:' enumeration for agent presets (vs permission L15) ==="
Select-String -Path $p -Pattern 'agent-preset-registry' -Context 0,8 | ForEach-Object { $_.Line; $_.Context.PostContext }

$p="C:\Users\Administrator\.dsh\profiles\web\cordis.patch.yml"
$lines=Get-Content $p
# Find preset-standard block extent: L99 to next '^- id: preset-' at L339
Write-Host "=== disabled entries within preset-standard (L99-338) ==="
for($i=98;$i -lt 338;$i++){
  if($lines[$i] -match 'disabled:\s*true'){ Write-Host "L$($i+1): $($lines[$i].Trim()) (prev id line: $(($lines[$i-1]).Trim()) / $(($lines[$i-2]).Trim()))" }
}

cd C:\Users\Administrator\.dsh\profiles\web
$bak=(Get-ChildItem cordis.patch.yml.bak-p1a-* | Select-Object -First 1).FullName
$bl = Get-Content $bak
Write-Host "=== BACKUP L99-120 ==="
$bl[98..119] | ForEach-Object {$_}
Write-Host "=== backup: line numbers of key markers ==="
for($i=0;$i -lt $bl.Count;$i++){
  if($bl[$i].Trim() -in @('- id: preset-standard','- id: agent-preset-registry','- id: preset-ptc')){ Write-Host "L$($i+1): $($bl[$i].Trim())" }
}

cd C:\Users\Administrator\.dsh\profiles\web
$cl = Get-Content cordis.patch.yml
Write-Host "current line count: $($cl.Count)"
Write-Host "=== markers ==="
for($i=0;$i -lt $cl.Count;$i++){
  $t=$cl[$i].Trim()
  if($t -in @('- id: preset-standard','- id: preset-full-tools','- id: agent-preset-registry','- id: preset-ptc','    id: standard','    id: full-tools','    plugins:')){ Write-Host "L$($i+1): $t" }
}

cd C:\Users\Administrator\.dsh\profiles\web
$bak=(Get-ChildItem cordis.patch.yml.bak-p1a-* | Select-Object -First 1).FullName
$bytes = [System.IO.File]::ReadAllBytes($bak)
$crlf = 0; $lf = 0
for($i=0;$i -lt [Math]::Min($bytes.Length,200000);$i++){
  if($bytes[$i] -eq 10){ if($i -gt 0 -and $bytes[$i-1] -eq 13){$crlf++} else {$lf++} }
}
Write-Host "backup: CRLF=$crlf bare-LF=$lf"
$cur = [System.IO.File]::ReadAllBytes("cordis.patch.yml")
$crlf2=0;$lf2=0
for($i=0;$i -lt $cur.Length;$i++){ if($cur[$i] -eq 10){ if($i -gt 0 -and $cur[$i-1] -eq 13){$crlf2++} else {$lf2++} } }
Write-Host "current: CRLF=$crlf2 bare-LF=$lf2"
